/* ─── Globe wireframe with SMIL animations ─── */
function GlobeWireframe() {
  const idPrefix = useId().replace(/:/g, "")
  const ggId = `${idPrefix}-gg`
  const gmgId = `${idPrefix}-gmg`
  const gmId = `${idPrefix}-gm`

  return (
    <svg
      aria-hidden="true"
      height="100%"
      style={{ overflow: "visible", display: "block" }}
      viewBox="-1 -1 802 402"
      width="100%"
    >
      <defs>
        <linearGradient
          gradientUnits="userSpaceOnUse"
          id={ggId}
          x1="0"
          x2="0"
          y1="0"
          y2="400"
        >
          <stop offset="0%" stopColor="var(--ga-grid)" />
          <stop offset="100%" stopColor="var(--ga-grid)" />
        </linearGradient>
        <linearGradient gradientTransform="rotate(90)" id={gmgId}>
          <stop offset=".7" stopColor="white" stopOpacity="1" />
          <stop offset="1" stopColor="white" stopOpacity="0" />
        </linearGradient>
        <mask id={gmId}>
          <rect fill={`url(#${gmgId})`} height="100%" width="100%" />
        </mask>
      </defs>
      <g mask={`url(#${gmId})`}>
        <circle cx="400" cy="400" fill="var(--ga-bg)" r="400" />
        {[
          -400, -328.701, -235.355, -123.097, 0, 123.097, 235.355, 328.701, 400,
        ].map((a) => (
          <path
            d={
              a <= 0
                ? `M 400 800 A ${a} 400 0 0 0 400 0`
                : `M 400 0 A ${a} 400 0 0 0 400 800`
            }
            fill="none"
            key={`v-${a}`}
            stroke={`url(#${ggId})`}
            strokeWidth="1"
            vectorEffect="non-scaling-stroke"
          />
        ))}
        {[
          [135.425, 100, 529.15],
          [53.59, 200, 692.82],
          [12.702, 300, 774.597],
          [0, 400, 800],
          [12.702, 500, 774.597],
          [53.59, 600, 692.82],
          [135.425, 700, 529.15],
        ].map(([x, y, w]) => (
          <path
            d={`M${x},${y} h${w}`}
            fill="none"
            key={`h-${y}`}
            stroke={`url(#${ggId})`}
            strokeWidth="1"
            vectorEffect="non-scaling-stroke"
          />
        ))}
      </g>
      {TRAIL_CONFIGS.map((t, i) => {
        const p = TRAIL_PATHS[i]
        if (!p) return null
        const id = `t${i}`,
          dur = `${t.dur}s`
        return (
          <g key={id} mask={`url(#${gmId})`}>
            <path
              d={p.d}
              fill="none"
              stroke={`url(#${id}g)`}
              strokeLinecap="round"
              strokeWidth="2"
              vectorEffect="non-scaling-stroke"
            >
              <animate
                attributeName="opacity"
                dur={dur}
                keyTimes={p.kt}
                repeatCount="indefinite"
                values={p.op}
              />
            </path>
            <defs>
              <radialGradient
                cx="100"
                cy="100"
                gradientUnits="userSpaceOnUse"
                id={`${id}g`}
                r="0"
              >
                <stop offset="0" stopColor={t.color} />
                <stop offset="0.4" stopColor={t.color} />
                <stop offset="1" stopColor={t.color} stopOpacity="0" />
                <animate
                  attributeName="cx"
                  dur={dur}
                  keyTimes={p.kt}
                  repeatCount="indefinite"
                  values={p.cx}
                />
                <animate
                  attributeName="cy"
                  dur={dur}
                  keyTimes={p.kt}
                  repeatCount="indefinite"
                  values={p.cy}
                />
                <animate
                  attributeName="r"
                  dur={dur}
                  keyTimes={p.kt}
                  repeatCount="indefinite"
                  values={p.r}
                />
              </radialGradient>
            </defs>
