              color: "var(--ga-badge)",
              opacity: active ? 1 : 0.6,
              transition: "opacity 200ms ease",
            }}
          >
            {badge}
          </span>
        )}
      </div>
      <div
        style={{
          height: 2,
          marginTop: 4,
          borderRadius: 9999,
          background: active ? "var(--ga-track-active)" : "transparent",
          overflow: "hidden",
          transition: "background 200ms ease",
        }}
      >
        <div
          style={{
            height: "100%",
            borderRadius: 9999,
            background: "var(--ga-fg)",
            width: active ? `${progress * 100}%` : "0%",
            transition: active ? "none" : "width 0ms",
          }}
        />
      </div>
    </button>
  )
}

const CYCLE_MS = 6000

/* ─── Main export ─── */
export default function GenerateAnything({
  title = "Generate anything",
  features = FEATURES,
}: {
  title?: string
  features?: Feature[]
}) {
  const [activeTab, setActiveTab] = useState("text")
  const [panelKey, setPanelKey] = useState(0)
  const [progress, setProgress] = useState(1)
  const startRef = useRef(Date.now())
  const rafRef = useRef<number | null>(null)

  const advanceTab = useCallback(() => {
    setActiveTab((prev) => {
      const idx = features.findIndex((f) => f.id === prev)
      return features[(idx + 1) % features.length].id
    })
    setPanelKey((k) => k + 1)
    startRef.current = Date.now()
  }, [features])

  useEffect(() => {
    function tick() {
      const elapsed = Date.now() - startRef.current
      const remaining = Math.max(1 - elapsed / CYCLE_MS, 0)
      setProgress(remaining)
      if (remaining <= 0) {
        advanceTab()
      }
      rafRef.current = requestAnimationFrame(tick)
    }
    rafRef.current = requestAnimationFrame(tick)
    return () => {
      if (rafRef.current !== null) cancelAnimationFrame(rafRef.current)
    }
  }, [advanceTab])

  const handleTabChange = useCallback(
    (id: string) => {
      if (id === activeTab) return
      setActiveTab(id)
      setPanelKey((k) => k + 1)
      startRef.current = Date.now()
      setProgress(1)
    },
    [activeTab]
  )

  return (
    <>
      <style>{`
        [data-generate-anything] {
          --ga-bg: #fafafa;
          --ga-surface: #fff;
          --ga-fg: #000;
          --ga-fg-muted: #888;
