              color: "var(--ga-fg)",
              margin: "0 0 36px",
              letterSpacing: "-0.03em",
              lineHeight: 1.2,
            }}
          >
            {title}
          </h2>
          <div style={{ display: "flex", flexDirection: "column" }}>
            {features.map((f) => {
              const isActive = f.id === activeTab
              return (
                <div key={f.id}>
                  <TabButton
                    active={isActive}
