                    onClick={handleWizardNext}
                    type="button"
                  >
                    {nextLabel}
                  </Button>
                )}
              </fieldset>
            </motion.div>
          ) : null}
        </motion.div>
      )
    }, [
      active,
      backLabel,
      baseId,
      canGoBack,
      completeDisabled,
      completeLabel,
      handleWizardBack,
      handleWizardComplete,
      handleWizardNext,
      isLastStep,
      nextDisabled,
      nextLabel,
      panelId,
      reduceMotion,
      showNavigation,
      steps,
    ])

    const wizardContextValue = useMemo<WizardExpandableContextValue>(
      () => ({
        activeStepId: active,
        activeIndex,
        totalSteps: steps.length,
        isLastStep,
        canGoBack,
        canGoNext: effectiveCanGoNext,
        goNext: handleWizardNext,
        goBack: handleWizardBack,
        complete: handleWizardComplete,
